    public static IReadOnlyList<CompanionDigitAssetProvenance> Provenance { get; } =
        Array.AsReadOnly(Entries.Select(static entry => entry.Provenance).ToArray());

    /// <summary>Creates independent encoded PNG buffers in Companion table order.</summary>
    public static IReadOnlyList<CompanionEncodedDigitTemplateSource> CreateSources()
    {
        return Entries
            .Select(static entry => new CompanionEncodedDigitTemplateSource(
                entry.Provenance.FontType,
                entry.Provenance.Digit,
                Convert.FromBase64String(entry.PngBase64)))
            .ToArray();
    }

    private sealed record Entry(
        CompanionDigitAssetProvenance Provenance,
        string PngBase64);
